mapper.select:
SELECT t.id AS `id`, t.order_id AS `orderId`, o.order_no AS `orderNo`, o.title AS `orderTitle`, o.status AS `orderStatus`, c.name AS `customerName`, t.material_type AS `materialType`, t.name AS `name`, t.spec AS `spec`, t.quantity AS `quantity`, t.deadline AS `deadline`, t.status AS `status`, t.created_at AS `createdAt`, (SELECT COUNT(*) FROM revision_feedback f WHERE f.task_id = t.id) AS `feedbackCount`, (SELECT f.content FROM revision_feedback f WHERE f.task_id = t.id ORDER BY f.round_no DESC LIMIT 1) AS `latestFeedback` FROM material_task t JOIN material_order o ON o.id = t.order_id AND o.deleted = 0 JOIN customer c ON c.id = o.customer_id WHERE t.assignee_id = #{assigneeId}
AND t.status = #{status}
ORDER BY FIELD(t.status, 'REVISION', 'DESIGNING', 'PENDING_CONFIRM', 'PENDING', 'CONFIRMED'), t.deadline, t.id

mapper.sql:
FROM material_task t JOIN material_order o ON o.id = t.order_id AND o.deleted = 0 JOIN customer c ON c.id = o.customer_id LEFT JOIN sys_user u ON u.id = t.assignee_id WHERE o.deleted = 0
AND t.status = #{status}
AND t.assignee_id = #{assigneeId}
AND t.order_id = #{orderId}
AND (t.name LIKE CONCAT('%', #{keyword}, '%') OR o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.title LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%'))
AND t.deadline IS NOT NULL AND t.deadline < CURDATE() AND t.status != 'CONFIRMED' AND o.status NOT IN ('COMPLETED', 'CANCELLED')
AND t.assignee_id IS NULL
AND EXISTS (SELECT 1 FROM operation_log l WHERE l.biz_type = 'TASK' AND l.biz_id = t.id AND l.action = 'TASK_DEADLINE_CHANGED')
